const resolveDeferredCharacterId = (value: string | number | null): number | null => {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value
  }
  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number(value)
    return Number.isFinite(parsed) ? parsed : null
  }
  return null
}

export const useServerChatLoader = ({
  ensureServerChatHistoryId,
  notification,
  t,
  scope
}: UseServerChatLoaderOptions) => {
  const [selectedAssistant, setSelectedAssistant] = useSelectedAssistant(null)
  const {
    messages,
    streaming,
    isProcessing,
    setHistory,
    setMessages,
    setIsLoading
  } = useChatBaseState(useStoreMessageOption)
  const messagesRef = React.useRef(messages)
  const streamingRef = React.useRef(streaming)
  const processingRef = React.useRef(isProcessing)
  const selectedAssistantRef = React.useRef(selectedAssistant)
  const {
    serverChatId,
    serverChatTitle,
    serverChatCharacterId,
    serverChatAssistantKind,
    serverChatAssistantId,
    serverChatPersonaMemoryMode,
    serverChatMetaLoaded,
    temporaryChat,
    setServerChatId,
    setServerChatLoadState,
    setServerChatLoadError,
    setServerChatTitle,
    setServerChatCharacterId,
    setServerChatAssistantKind,
    setServerChatAssistantId,
    setServerChatPersonaMemoryMode,
    setServerChatState,
    setServerChatVersion,
    setServerChatTopic,
    setServerChatClusterId,
    setServerChatSource,
    setServerChatExternalRef,
    setServerChatMetaLoaded
  } = useStoreMessageOption(
    (state) => ({
      serverChatId: state.serverChatId,
      serverChatTitle: state.serverChatTitle,
      serverChatCharacterId: state.serverChatCharacterId,
      serverChatAssistantKind: state.serverChatAssistantKind,
      serverChatAssistantId: state.serverChatAssistantId,
      serverChatPersonaMemoryMode: state.serverChatPersonaMemoryMode,
      serverChatMetaLoaded: state.serverChatMetaLoaded,
      temporaryChat: state.temporaryChat,
      setServerChatId: state.setServerChatId,
      setServerChatLoadState: state.setServerChatLoadState,
      setServerChatLoadError: state.setServerChatLoadError,
      setServerChatTitle: state.setServerChatTitle,
      setServerChatCharacterId: state.setServerChatCharacterId,
      setServerChatAssistantKind: state.setServerChatAssistantKind,
      setServerChatAssistantId: state.setServerChatAssistantId,
      setServerChatPersonaMemoryMode: state.setServerChatPersonaMemoryMode,
      setServerChatState: state.setServerChatState,
      setServerChatVersion: state.setServerChatVersion,
      setServerChatTopic: state.setServerChatTopic,
      setServerChatClusterId: state.setServerChatClusterId,
      setServerChatSource: state.setServerChatSource,
      setServerChatExternalRef: state.setServerChatExternalRef,
      setServerChatMetaLoaded: state.setServerChatMetaLoaded
    }),
    shallow
  )

  const serverChatLoadRef = React.useRef<{
    chatId: string | null
    controller: AbortController | null
    inFlight: boolean
    loaded: boolean
  }>({ chatId: null, controller: null, inFlight: false, loaded: false })
  const serverChatDebounceRef = React.useRef<{
    chatId: string | null
    timer: ReturnType<typeof setTimeout> | null
  }>({ chatId: null, timer: null })

  messagesRef.current = messages
  streamingRef.current = streaming
  processingRef.current = isProcessing
  selectedAssistantRef.current = selectedAssistant

  React.useEffect(() => {
    return () => {
      if (serverChatDebounceRef.current.timer) {
        clearTimeout(serverChatDebounceRef.current.timer)
      }
      if (serverChatLoadRef.current.controller) {
        serverChatLoadRef.current.controller.abort()
      }
    }
  }, [])

  React.useEffect(() => {
    if (!serverChatId) return
    if (
      shouldSkipLoadedServerChatReload({
        activeServerChatId: serverChatId,
        loadedChatId: serverChatLoadRef.current.chatId,
        loaded: serverChatLoadRef.current.loaded,
        currentMessages: messagesRef.current
      })
    ) {
      return
    }
    if (serverChatLoadRef.current.inFlight) {
      if (serverChatLoadRef.current.chatId === serverChatId) {
        return
      }
      if (serverChatLoadRef.current.controller) {
        serverChatLoadRef.current.controller.abort()
      }
      serverChatLoadRef.current.inFlight = false
    }

    if (serverChatDebounceRef.current.timer) {
      clearTimeout(serverChatDebounceRef.current.timer)
    }

    serverChatDebounceRef.current.chatId = serverChatId
    serverChatDebounceRef.current.timer = setTimeout(() => {
      const controller = new AbortController()
      let ownedSelectionRevision = getSelectedAssistantOperationRevision()
      const canCommitCurrentLoad = () =>
        useStoreMessageOption.getState().serverChatId === serverChatId &&
        shouldCommitServerChatLoadResult({
          requestedChatId: serverChatId,
          activeServerChatId: serverChatLoadRef.current.chatId,
          requestController: controller,
          activeController: serverChatLoadRef.current.controller
        })
      const applyOwnedAssistantSelection = async (selection: Parameters<typeof setSelectedAssistant>[0]) => {
        const before = ownedSelectionRevision
        if (!canCommitCurrentLoad() || getSelectedAssistantOperationRevision() !== before) return false
        await setSelectedAssistant(selection, { isCurrent: () => {
          const revision = getSelectedAssistantOperationRevision()
          // This operation increments the existing revision synchronously. A
          // later picker operation must win even before React rerenders.
          return canCommitCurrentLoad() && (revision === before || revision === before + 1)
        } })
        ownedSelectionRevision = before + 1
        return canCommitCurrentLoad() && getSelectedAssistantOperationRevision() === ownedSelectionRevision
      }
      serverChatLoadRef.current = {
        chatId: serverChatId,
        controller,
        inFlight: true,
        loaded: false
      }

      const loadServerChat = async () => {
        let didLoadSuccessfully = false
        let snapshot: ServicePromptSnapshot | undefined
        let stopWatchingAuthority: (() => void) | undefined
        let pendingAssistantPresentation: Promise<unknown> | undefined
        try {
          setIsLoading(true)
          setServerChatLoadState("loading")
          setServerChatLoadError(null)
          snapshot = await loadServicePromptSnapshot([], { signal: controller.signal })
          snapshot.scopeInvalidatedSignal.addEventListener("abort", () => controller.abort(), { once: true })
          if (snapshot.scopeSignal.aborted || !canCommitCurrentLoad()) return
          stopWatchingAuthority = watchServerChatLoadAuthority(snapshot, controller)

          let assistantName = "Assistant"
          let chatTitle = serverChatTitle || ""
          let characterId = serverChatCharacterId ?? null
          let assistantKind = serverChatAssistantKind
          let assistantId = serverChatAssistantId
          let personaMemoryMode = serverChatPersonaMemoryMode
          let restoreAssistantSelection = true

          if (!serverChatMetaLoaded) {
            try {
              const chat = await tldwClient.getChat(
                serverChatId,
                { scope, signal: snapshot.scopeSignal, requestScope: snapshot.requestScope }
              )
              if (!canCommitCurrentLoad()) {
                return
              }
              const validatedServerChatId = validateCachedServerChatId({
                cachedId: serverChatId,
                serverScope: {
                  scope_type: String((chat as any)?.scope_type || ""),
                  workspace_id:
                    typeof (chat as any)?.workspace_id === "string"
                      ? (chat as any).workspace_id
                      : null
                },
                expectedScope: scope || { type: "global" }
              })
              if (!validatedServerChatId) {
                setServerChatId(null)
                return
              }
              const meta = chat as unknown as Record<string, unknown>
              chatTitle = String(meta?.title || chatTitle || "")
              const resolvedAssistantIdentity =
                resolveServerChatAssistantIdentity(meta)
              assistantKind = resolvedAssistantIdentity.assistantKind
              assistantId = resolvedAssistantIdentity.assistantId
              characterId = resolvedAssistantIdentity.characterId
              personaMemoryMode = resolvedAssistantIdentity.personaMemoryMode
              restoreAssistantSelection = getSelectedAssistantOperationRevision() === ownedSelectionRevision
              setServerChatTitle(chatTitle || "")
              setServerChatCharacterId(characterId)
              setServerChatAssistantKind(assistantKind)
              setServerChatAssistantId(assistantId)
              setServerChatPersonaMemoryMode(personaMemoryMode)
              setServerChatState(
                normalizeConversationState(
                  (meta?.state as string | null | undefined) ??
                    (meta?.conversation_state as string | null | undefined)
                )
              )
              setServerChatVersion(
                typeof meta?.version === "number" ? meta.version : null
              )
              setServerChatTopic(
                typeof meta?.topic_label === "string"
                  ? meta.topic_label
                  : null
              )
              setServerChatClusterId(
                typeof meta?.cluster_id === "string" ? meta.cluster_id : null
              )
              setServerChatSource(
                typeof meta?.source === "string" ? meta.source : null
              )
              setServerChatExternalRef(
                typeof meta?.external_ref === "string"
                  ? meta.external_ref
                  : null
              )
              setServerChatMetaLoaded(true)
            } catch (error) {
              if (isMissingServerChatReferenceError(error) && canCommitCurrentLoad()) {
                setServerChatId(null)
                return
              }
              // ignore metadata failures; still try to load messages
            }
          }

          const deferredAssistantPresentationPromise = (async () => {
            if (!restoreAssistantSelection) return null
            let syncedSettings = null
            if (assistantKind == null && characterId == null) {
              try {
                syncedSettings = await syncChatSettingsForServerChat({
                  historyId: null,
                  serverChatId,
                  allowScratchFallback: false
                })
              } catch {
                syncedSettings = null
              }
            }

            if (assistantKind === "persona" && assistantId) {
              try {
                const persona = await tldwClient.getPersonaProfile(assistantId, {
                  signal: snapshot!.scopeSignal, requestScope: snapshot!.requestScope
                })
                if (persona) {
                  if (!canCommitCurrentLoad()) {
                    return null
                  }
                  const nextAssistantName = persona.name || "Persona"
                  const selection = personaToAssistantSelection({
                    ...persona,
                    id: assistantId,
                    name: nextAssistantName
                  })
                  if (!await applyOwnedAssistantSelection(selection)) return null
                  return {
                    assistantName: nextAssistantName,
                    assistantAvatarUrl: selection?.avatar_url ?? null
                  }
                }
              } catch (error) {
                reportDeferredAssistantPresentationError({
                  stage: "persona-profile",
                  assistantKind,
                  assistantId,
                  characterId: resolveDeferredCharacterId(characterId),
                  error
                })
                if (!canCommitCurrentLoad()) {
                  return null
                }
                const selection = personaToAssistantSelection({
                  id: assistantId,
                  name: "Persona"
                })
                if (!await applyOwnedAssistantSelection(selection)) return null
                return {
                  assistantName: selection?.name || "Persona",
                  assistantAvatarUrl: selection?.avatar_url ?? null
                }
              }
            } else if (characterId != null) {
              try {
                const character = await tldwClient.getCharacter(characterId, {
                  signal: snapshot!.scopeSignal, requestScope: snapshot!.requestScope
                })
                if (character) {
                  if (!canCommitCurrentLoad()) {
                    return null
                  }
                  const selection = characterToAssistantSelection({
                    ...character,
                    id: String(character.id ?? characterId)
                  })
                  if (!await applyOwnedAssistantSelection(selection)) return null
                  return {
                    assistantName:
                      selection?.name ||
                      character.name ||
                      character.title ||
                      assistantName,
                    assistantAvatarUrl: selection?.avatar_url ?? null
                  }
                }
              } catch (error) {
                reportDeferredAssistantPresentationError({
                  stage: "character-profile",
                  assistantKind,
                  assistantId,
                  characterId: resolveDeferredCharacterId(characterId),
                  error
                })
              }
              if (!canCommitCurrentLoad()) {
                return null
              }
              const fallbackState = resolveEffectiveAssistantState({
                tracked: {
                  assistantKind,
                  assistantId,
                  characterId
                },
                draftSelection: selectedAssistantRef.current
              })
              const selection =
                effectiveAssistantStateToSelection(fallbackState)
              if (selection) {
                if (!await applyOwnedAssistantSelection(selection)) return null
                return {
                  assistantName: selection.name,
                  assistantAvatarUrl: selection.avatar_url ?? null
                }
              }
              if (!await applyOwnedAssistantSelection(null)) return null
              return null
            }

            if (!canCommitCurrentLoad()) {
              return null
            }
            const effectiveAssistantState = resolveEffectiveAssistantState({
              tracked: {
                assistantKind,
                assistantId,
                characterId
              },
              settings: syncedSettings
            })
            const selection =
              effectiveAssistantStateToSelection(effectiveAssistantState)
            if (selection) {
              if (!await applyOwnedAssistantSelection(selection)) return null
              return {
                assistantName: selection.name,
                assistantAvatarUrl: selection.avatar_url ?? null
              }
            }
            if (!await applyOwnedAssistantSelection(null)) return null
            return null
          })()

          pendingAssistantPresentation = deferredAssistantPresentationPromise

          const list = await fetchAllServerChatMessages(
            ({ limit, offset, signal }) =>
              tldwClient.listChatMessages(
                serverChatId,
                {
                  include_deleted: "false",
                  include_metadata: "true",
                  include_images: "true",
                  render_placeholders: assistantKind === "character" || characterId != null ? "true" : "false",
                  limit,
                  offset
                },
                { signal, scope, requestScope: snapshot!.requestScope }
              ),
            {
              signal: controller.signal
            }
          )

          if (list.some(message => message.role === "user" && (message.images?.length ?? 0) > 1)) {
            throw new Error("This conversation has multiple images in one user message. Chat currently supports one image per turn. Your local work has been kept; open a new conversation to continue.")
          }
          const mappedMessages = mapServerChatMessagesToPlaygroundMessages({
            serverMessages: list,
            assistantName,
            characterId
          })
          if (!canCommitCurrentLoad()) {
            return
          }
          const active = streamingRef.current || processingRef.current
          if (!active) {
            const merged = reconcileServerChatMessages(messagesRef.current, mappedMessages)
            setHistory(merged.map(message => ({ role: message.role, content: message.message, image: message.images?.[0], messageType: message.messageType })))
            setMessages(merged)
          }
          const shouldApplyDeferredAssistantPresentation =
            !active
          if (shouldApplyDeferredAssistantPresentation) {
            void deferredAssistantPresentationPromise
              .then((presentation) => {
                if (!presentation || !canCommitCurrentLoad()) {
                  return
                }
                setMessages((currentMessages) =>
                  applyAssistantPresentationToMessages({
                    messages: currentMessages,
                    assistantName: presentation.assistantName,
                    assistantAvatarUrl: presentation.assistantAvatarUrl
                  })
                )
              })
              .catch((error) => {
                reportDeferredAssistantPresentationError({
                  stage: "presentation-apply",
                  assistantKind,
                  assistantId,
                  characterId: resolveDeferredCharacterId(characterId),
                  error
                })
              })
          }
          if (!temporaryChat && !active) {
            if (!canCommitCurrentLoad()) {
              return
            }
            const beforeMirror = useStoreMessageOption.getState().messages
            try {
              const localHistoryId = await ensureServerChatHistoryId(
                serverChatId,
                chatTitle || undefined,
                snapshot.scopeSignal,
                snapshot
              )
              if (!canCommitCurrentLoad()) {
                return
              }
              if (localHistoryId) {
                try {
                  await syncChatSettingsForServerChat({
                    historyId: localHistoryId,
                    serverChatId,
                    allowScratchFallback: false
                  })
                } catch {
                  // Best-effort settings sync.
                }
                if (!canCommitCurrentLoad() || streamingRef.current || processingRef.current) return
                const mirror = await reconcileServerChatMirror({
                  historyId: localHistoryId, chatId: serverChatId,
                  ownerKey: serverChatMirrorOwnerKey(snapshot), messages: mappedMessages,
                  signal: snapshot.scopeSignal
                })
                if (!canCommitCurrentLoad() || streamingRef.current || processingRef.current ||
                  useStoreMessageOption.getState().historyId !== localHistoryId) return
                const merged = reconcileServerChatMessages(
                  useStoreMessageOption.getState().messages,
                  formatToMessage(mirror.rows),
                  beforeMirror
                ).map(message => {
                  const id = message.serverMessageId ? mirror.localIds.get(message.serverMessageId) : undefined
                  return id && message.id !== id ? { ...message, id } : message
                })
                setHistory(merged.map(message => ({ role: message.role, content: message.message, image: message.images?.[0], messageType: message.messageType })))
                setMessages(merged)
              }
            } catch {
              if (!canCommitCurrentLoad()) {
                return
              }
              // Local mirror is best-effort for server chats.
            }
          }
          if (!canCommitCurrentLoad()) {
            return
          }
          if (chatTitle) {
            updatePageTitle(chatTitle)
          }
          didLoadSuccessfully = true
          setServerChatLoadError(null)
          setServerChatLoadState("loaded")
        } catch (e: unknown) {
          const message = e instanceof Error ? e.message : String(e || "")
          const isAbort =
            e instanceof Error && e.name === "AbortError"
              ? true
              : message.toLowerCase().includes("abort")
          if (!isAbort && isMissingServerChatReferenceError(e) && canCommitCurrentLoad()) {
            setServerChatId(null)
            return
          }
          if (!isAbort && canCommitCurrentLoad()) {
            const description =
              message ||
              t("common:serverChatLoadError", {
                defaultValue:
                  "Failed to load server chat. Check your connection and try again."
              })
            setServerChatLoadState("failed")
            setServerChatLoadError(description)
            notification.error({
              message: t("error", { defaultValue: "Error" }),
              description
            })
          }
        } finally {
          if (useStoreMessageOption.getState().serverChatId === serverChatId) setIsLoading(false)
          // Messages are ready independently of optional profile enrichment.
          // Keep this load's authority alive until that guarded work settles.
          await pendingAssistantPresentation?.catch(() => undefined)
          stopWatchingAuthority?.()
          snapshot?.release()
          if (serverChatLoadRef.current.controller === controller) {
            serverChatLoadRef.current = {
              chatId: serverChatId,
              controller: null,
              inFlight: false,
              loaded: didLoadSuccessfully
            }
          }
        }
      }

      void loadServerChat()
    }, 200)

    return () => {
      if (serverChatDebounceRef.current.timer) {
        clearTimeout(serverChatDebounceRef.current.timer)
        serverChatDebounceRef.current.timer = null
      }
    }
  }, [
    ensureServerChatHistoryId,
    notification,
    serverChatAssistantId,
    serverChatAssistantKind,
    serverChatCharacterId,
    serverChatId,
    serverChatMetaLoaded,
    serverChatPersonaMemoryMode,
    serverChatTitle,
    setHistory,
    setIsLoading,
    setMessages,
    setSelectedAssistant,
    setServerChatAssistantId,
    setServerChatAssistantKind,
    setServerChatCharacterId,
    setServerChatClusterId,
    setServerChatExternalRef,
    setServerChatId,
    setServerChatLoadError,
    setServerChatLoadState,
    setServerChatMetaLoaded,
    setServerChatPersonaMemoryMode,
    setServerChatSource,
    setServerChatState,
    setServerChatTitle,
    setServerChatTopic,
    setServerChatVersion,
    scope,
    t,
    temporaryChat
  ])
}

import { type ChatHistory, type Message } from "~/store/option"
import {
  deleteChatForEdit,
  formatToChatHistory,
  formatToMessage,
  saveHistory,
  saveMessage,
  updateMessageByIndex
} from "@/db/dexie/helpers"
import { generateBranchMessage } from "@/db/dexie/branch"
import { getPromptById, getSessionFiles, UploadedFile } from "@/db"
import { tldwClient, type ConversationState } from "@/services/tldw/TldwApiClient"
import { normalizeConversationState } from "@/utils/conversation-state"
import type { NotificationInstance } from "antd/es/notification/interface"
import type { ChatScope } from "@/types/chat-scope"

export const createRegenerateLastMessage = ({
  validateBeforeSubmitFn,
  history,
  messages,
  setHistory,
  setMessages,
  onSubmit,
  beforeSubmit
}: {
  validateBeforeSubmitFn: () => boolean
  history: ChatHistory
  messages: Message[]
  setHistory: (history: ChatHistory) => void
  setMessages: (messages: Message[]) => void
  onSubmit: (params: any) => Promise<unknown>
  beforeSubmit?: (params: {
    lastAssistant: Message
    lastAssistantIndex: number
    userContent: string
    userImage: string
    userMessageType: Message["messageType"] | undefined
    newHistory: ChatHistory
    nextMessages: Message[]
  }) => Promise<
    | {
        memory?: ChatHistory
        messages?: Message[]
        submitExtras?: Record<string, unknown>
      }
    | void
  >
}) => {
  return async () => {
    if (typeof setHistory !== "function") {
      console.error("[chat] regenerate aborted: setHistory is not callable", {
        setHistoryType: typeof setHistory
      })
      return
    }
    const isOk = validateBeforeSubmitFn()

    if (!isOk) {
      return
    }
    const lastAssistantIndex = (() => {
      for (let i = messages.length - 1; i >= 0; i--) {
        if (messages[i]?.isBot) return i
      }
      return -1
    })()
    if (lastAssistantIndex < 0) {
      return
    }

    const lastAssistant = messages[lastAssistantIndex]
    const historyUser = (() => {
      for (let i = history.length - 1; i >= 0; i--) {
        if (history[i]?.role === "user") {
          return { index: i, entry: history[i] }
        }
      }
      return null
    })()
    const messageUser = (() => {
      for (let i = lastAssistantIndex - 1; i >= 0; i--) {
        if (!messages[i]?.isBot) return messages[i]
      }
      return null
    })()

    const userContent =
      historyUser?.entry?.content ?? messageUser?.message ?? ""
    const userImage =
      historyUser?.entry?.image || messageUser?.images?.[0] || ""
    if (!userContent.trim() && !userImage) {
      return
    }
    const userMessageType =
      historyUser?.entry?.messageType || messageUser?.messageType

    const newHistory = historyUser
      ? history.slice(0, historyUser.index)
      : history.slice(0, Math.max(history.length - 2, 0))
    const nextMessages = messages.filter((_, idx) => idx !== lastAssistantIndex)

    const beforeSubmitResult =
      (await beforeSubmit?.({
        lastAssistant,
        lastAssistantIndex,
        userContent,
        userImage,
        userMessageType,
        newHistory,
        nextMessages
      })) || {}
    const submitHistory = beforeSubmitResult.memory ?? newHistory
    const submitMessages = beforeSubmitResult.messages ?? nextMessages
    const submitExtras = beforeSubmitResult.submitExtras ?? {}

    setHistory(submitHistory)
    setMessages(submitMessages)

    const newController = new AbortController()
    await onSubmit({
      message: userContent,
      image: userImage,
      isRegenerate: true,
      memory: submitHistory,
      messages: submitMessages,
      controller: newController,
      messageType: userMessageType,
      regenerateFromMessage: lastAssistant,
      ...submitExtras
    })
  }
}

export const createEditMessage = ({
  messages,
  history,
  setMessages,
  setHistory,
  historyId,
  validateBeforeSubmitFn,
  onSubmit
}: {
  messages: Message[]
  history: ChatHistory
  setMessages: (messages: Message[]) => void
  setHistory: (history: ChatHistory) => void
  historyId: string | null
  validateBeforeSubmitFn: () => boolean
  onSubmit: (params: any) => Promise<unknown>
}) => {
  return async (
    index: number,
    message: string,
    isHuman: boolean,
    isSend: boolean
  ) => {
    const newHistory = history

    // if human message and send then only trigger the submit
    if (isHuman && isSend) {
      const isOk = validateBeforeSubmitFn()

      if (!isOk) {
        return
      }

      const currentHumanMessage = messages[index]
      const updatedMessages = messages.map((msg, idx) =>
        idx === index ? { ...msg, message } : msg
      )
      const previousMessages = updatedMessages.slice(0, index + 1)
      setMessages(previousMessages)
      const previousHistory = newHistory.slice(0, index)
      setHistory(previousHistory)
      await updateMessageByIndex(historyId, index, message)
      await deleteChatForEdit(historyId, index)
      const abortController = new AbortController()
      await onSubmit({
        message: message,
        image: currentHumanMessage.images[0] || "",
        isRegenerate: true,
        messages: previousMessages,
        memory: previousHistory,
        controller: abortController
      })
      return
    }
    const updatedMessages = messages.map((msg, idx) =>
      idx === index ? { ...msg, message } : msg
    )
    setMessages(updatedMessages)
    const updatedHistory = newHistory.map((item, idx) =>
      idx === index ? { ...item, content: message } : item
    )
    setHistory(updatedHistory)
    await updateMessageByIndex(historyId, index, message)
  }
}

export const createBranchMessage = ({
  notification,
  setMessages,
  setHistory,
  historyId,
  setHistoryId,
  setContext,
  setSelectedSystemPrompt,
  setSystemPrompt,
  serverChatId,
  scope,
  setServerChatId,
  setServerChatState,
  setServerChatVersion,
  setServerChatTitle,
  setServerChatCharacterId,
  setServerChatMetaLoaded,
  setServerChatTopic,
  setServerChatClusterId,
  setServerChatSource,
  setServerChatExternalRef,
  characterId,
  chatTitle,
  serverChatState,
  serverChatTopic,
  serverChatClusterId,
  serverChatSource,
  serverChatExternalRef,
  messages,
  history,
  onServerChatMutated,
  serverOnly = false
}: {
  setMessages: (messages: Message[]) => void
  setHistory: (history: ChatHistory) => void
  historyId: string | null
  setHistoryId: (id: string | null) => void
  setSelectedSystemPrompt?: (prompt: string) => void
  setSystemPrompt?: (prompt: string) => void
  setContext?: (context: UploadedFile[]) => void
  serverChatId?: string | null
  scope?: ChatScope
  setServerChatId?: (id: string | null) => void
  setServerChatState?: (state: ConversationState | null) => void
  setServerChatVersion?: (version: number | null) => void
  setServerChatTitle?: (title: string | null) => void
  setServerChatCharacterId?: (id: string | number | null) => void
  setServerChatMetaLoaded?: (loaded: boolean) => void
  setServerChatTopic?: (topic: string | null) => void
  setServerChatClusterId?: (clusterId: string | null) => void
  setServerChatSource?: (source: string | null) => void
  setServerChatExternalRef?: (ref: string | null) => void
  characterId?: string | number | null
  chatTitle?: string | null
  serverChatState?: ConversationState | null
  serverChatTopic?: string | null
  serverChatClusterId?: string | null
  serverChatSource?: string | null
  serverChatExternalRef?: string | null
  messages?: Message[]
  history?: ChatHistory
  onServerChatMutated?: () => void
  serverOnly?: boolean
  notification: NotificationInstance
}) => {
  const createLocalBranch = async (index: number): Promise<string | null> => {
    if (!historyId) {
      // No persisted history; nothing to branch from.
      return null
    }

    try {
      const newBranch = await generateBranchMessage(historyId, index)
      setHistory(formatToChatHistory(newBranch.messages))
      setMessages(formatToMessage(newBranch.messages))
      setHistoryId(newBranch.history.id)
      const systemFiles = await getSessionFiles(newBranch.history.id)
      if (setContext) {
        setContext(systemFiles)
      }

      const lastUsedPrompt = newBranch?.history?.last_used_prompt
      if (lastUsedPrompt) {
        if (lastUsedPrompt.prompt_id) {
          const prompt = await getPromptById(lastUsedPrompt.prompt_id)
          if (prompt && setSelectedSystemPrompt) {
            setSelectedSystemPrompt(lastUsedPrompt.prompt_id)
          }
        }
        if (setSystemPrompt) {
          setSystemPrompt(lastUsedPrompt.prompt_content)
        }
      }
      return newBranch.history.id
    } catch (e) {
      return null
    }
  }

  const createLocalBranchFromSnapshot = async (
    index: number,
    branchTitle: string
  ): Promise<string | null> => {
    if (!messages || messages.length === 0) {
      return null
    }

    const snapshot = messages.slice(0, index + 1)
    if (snapshot.length === 0) {
      return null
    }

    try {
      const newHistory = await saveHistory(branchTitle, false, "branch")
      const savedMessages: any[] = []

      for (let i = 0; i < snapshot.length; i++) {
        const msg = snapshot[i]
        const role =
          msg.name === "System"
            ? "system"
            : msg.isBot
              ? "assistant"
              : "user"
        const name =
          msg.name ||
          (role === "assistant"
            ? "Assistant"
            : role === "system"
              ? "System"
              : "You")
        const saved = await saveMessage({
          history_id: newHistory.id,
          name,
          role,
          content: String(msg.message ?? ""),
          images: msg.images || [],
          source: msg.sources || [],
          time: i,
          message_type: msg.messageType,
          clusterId: msg.clusterId,
          modelId: msg.modelId,
          modelImage: msg.modelImage,
          modelName: msg.modelName,
          parent_message_id: msg.parentMessageId ?? null,
          documents: msg.documents
        })
        savedMessages.push(saved)
      }

      setHistory(formatToChatHistory(savedMessages))
      setMessages(formatToMessage(savedMessages))
      setHistoryId(newHistory.id)
      if (setContext) {
        setContext([])
      }
      return newHistory.id
    } catch (e) {
      return null
    }
  }

  return async (index: number): Promise<string | null> => {
    // When a server-backed character chat is active, create a new server chat
    // branched from the current context and mirror the prefix messages.
    if (serverChatId) {
      try {
        await tldwClient.initialize().catch(() => null)

        let resolvedTitle = (chatTitle || "").trim()
        let resolvedCharacterId = characterId ?? null
        let resolvedState = normalizeConversationState(
          serverChatState || "in-progress"
        )
        try {
          const chat = await tldwClient.getChat(
            serverChatId,
            scope ? { scope } : undefined
          )
          if (!resolvedTitle) {
            resolvedTitle = (chat?.title || "").trim()
          }
          const chatCharacterId =
            (chat as any)?.character_id ?? (chat as any)?.characterId ?? null
          if (chatCharacterId != null) {
            resolvedCharacterId = chatCharacterId
          }
          resolvedState = normalizeConversationState(
            (chat as any)?.state ??
              (chat as any)?.conversation_state ??
              resolvedState
          )
        } catch (e) {
          // server metadata fetch failed; continue with resolved defaults
        }

        const originalTitle =
          resolvedTitle || (serverChatTopic || "").trim() || "Extension chat"
        const shortId = String(serverChatId).slice(0, 8)
        const base =
          originalTitle.length > 60
            ? `${originalTitle.slice(0, 57)}…`
            : originalTitle
        const branchTitle = `${base} [${shortId}] · msg #${index + 1}`

        if (resolvedCharacterId == null) {
          throw new Error("Cannot branch server chat without character_id")
        }

        const payload: Record<string, any> = {
          title: branchTitle,
          parent_conversation_id: serverChatId,
          state: resolvedState,
          topic_label: serverChatTopic || undefined,
          cluster_id: serverChatClusterId || undefined,
          source: serverChatSource || undefined,
          external_ref: serverChatExternalRef || undefined
        }
        if (resolvedCharacterId != null) {
          payload.character_id = resolvedCharacterId
        }

        const created = await tldwClient.createChat(
          payload,
          scope ? { scope } : undefined
        )
        const rawId =
          (created as any)?.id ?? (created as any)?.chat_id ?? created
        const newChatId = rawId != null ? String(rawId) : ""
        if (!newChatId) {
          throw new Error("Failed to create server branch chat")
        }
        onServerChatMutated?.()

        const snapshot: ChatHistory =
          (history && Array.isArray(history) ? history : []).slice(
            0,
            index + 1
          )

        for (const msg of snapshot) {
          const content = (msg.content || "").trim()
          if (!content) continue
          const role =
            msg.role === "system" ||
            msg.role === "assistant" ||
            msg.role === "user"
              ? msg.role
              : "user"
          await tldwClient.addChatMessage(
            newChatId,
            {
              role,
              content
            },
            scope ? { scope } : undefined
          )
        }

        if (setServerChatId) {
          setServerChatId(newChatId)
        }
        if (setServerChatState) {
          setServerChatState(
            (created as any)?.state ??
              (created as any)?.conversation_state ??
              "in-progress"
          )
        }
        if (setServerChatVersion) {
          setServerChatVersion((created as any)?.version ?? null)
        }
        if (setServerChatTopic) {
          setServerChatTopic((created as any)?.topic_label ?? null)
        }
        if (setServerChatClusterId) {
          setServerChatClusterId((created as any)?.cluster_id ?? null)
        }
        if (setServerChatSource) {
          setServerChatSource((created as any)?.source ?? null)
        }
        if (setServerChatExternalRef) {
          setServerChatExternalRef((created as any)?.external_ref ?? null)
        }
        if (setServerChatTitle) {
          setServerChatTitle(
            String((created as any)?.title ?? chatTitle ?? "")
          )
        }
        if (setServerChatCharacterId) {
          setServerChatCharacterId(
            (created as any)?.character_id ?? characterId ?? null
          )
        }
        if (setServerChatMetaLoaded) {
          setServerChatMetaLoaded(true)
        }

        if (messages && messages.length > 0) {
          const slicedMessages = messages.slice(0, index + 1)
          setMessages(slicedMessages)
          if (history && history.length > 0) {
            setHistory(snapshot)
          }
        }

        return newChatId
      } catch (e) {
        // server branch failed; attempt local fallback
        if (serverOnly) {
          notification.error({
            message: "Branch failed",
            description:
              "Unable to create a branched server chat. Check your server connection and try again."
          })
          return null
        }
        const fallbackTitle = `${String(serverChatId).slice(0, 8)} · msg #${
          index + 1
        }`
        const fallbackId =
          (await createLocalBranch(index)) ??
          (await createLocalBranchFromSnapshot(index, fallbackTitle))
        if (fallbackId) {
          notification.warning({
            message: "Branch fallback",
            description:
              "Server branch failed. Created a local branch instead."
          })
          return fallbackId
        }
        notification.error({
          message: "Branch failed",
          description:
            "Unable to create a branched server chat. Check your server connection and try again."
        })
        return null
      }
    }

    // Local Dexie-backed branch (existing behavior)
    return (
      (await createLocalBranch(index)) ??
      (await createLocalBranchFromSnapshot(index, `Branch · msg #${index + 1}`))
    )
  }
}

export const createStopStreamingRequest = (
  abortController: AbortController | null,
  setAbortController: (controller: AbortController | null) => void
) => {
  return () => {
    if (abortController) {
      abortController.abort()
      setAbortController(null)
    }
  }
}

