  async persistCharacterCompletion(
    chat_id: string | number,
    payload: Record<string, any>,
    options?: {
      scope?: ChatScope
      signal?: AbortSignal
      requestScope?: ServicePromptRequestScope
    }
  ): Promise<any> {
    const cid = String(chat_id)
